problems.reference_solution:
def first_index(nums, target):
    """Return the first index of target in the ascending list nums, or -1."""
    low, high = 0, len(nums)
    # The answer, if any, stays in [low, high): everything before low is smaller.
    while low < high:
        middle = (low + high) // 2
        if nums[middle] < target:
            low = middle + 1
        else:
            high = middle
    return low if low < len(nums) and nums[low] == target else -1

