from solution import *


class _Watched(list):
    """A list that counts element reads and refuses to be scanned."""

    def __init__(self, values):
        super().__init__(values)
        self.reads = 0

    def __getitem__(self, key):
        if isinstance(key, slice):
            raise AssertionError('slicing copies part of the list: read single elements')
        self.reads += 1
        return super().__getitem__(key)

    def _refuse(self, *args, **kwargs):
        raise AssertionError('scanning the list is linear: read single elements by index')

    __iter__ = __contains__ = __reversed__ = index = count = copy = _refuse


def test_example_1():
    """The first of three equal values."""
    assert first_index([1, 2, 2, 2, 5], 2) == 1


def test_example_2():
    """The target falls between two values."""
    assert first_index([1, 3, 5], 4) == -1


def test_empty_list():
    """Nothing can be found in an empty list."""
    assert first_index([], 3) == -1


def test_outside_the_range():
    """Targets below the first and above the last value."""
    assert first_index([2, 4, 6], 1) == -1
    assert first_index([2, 4, 6], 7) == -1


def test_ends():
