    assert first_index([7] * 1000, 7) == 0


def test_logarithmic_reads():
    """A million values, searched with a few dozen reads."""
    nums = _Watched(value // 3 for value in range(1000000))
    assert first_index(nums, 200000) == 600000
    assert first_index(nums, -1) == -1
    assert nums.reads <= 100

