def sorted_squares(nums):
    """Return the squares of the ascending list nums in ascending order."""
    result = [0] * len(nums)
    left, right = 0, len(nums) - 1
    for place in range(len(nums) - 1, -1, -1):
        if abs(nums[left]) > abs(nums[right]):
            result[place] = nums[left] * nums[left]
            left += 1
        else:
            result[place] = nums[right] * nums[right]
            right -= 1
    return result

