problems.reference_solution:
def count_stretches(nums, k):
    """Return the number of contiguous stretches of nums that sum to k."""
    seen = {0: 1}
    total = 0
    count = 0
    for value in nums:
        total += value
        count += seen.get(total - k, 0)
        seen[total] = seen.get(total, 0) + 1
    return count

