import random

from solution import *


def _slow(nums, k):
    count = 0
    for start in range(len(nums)):
        total = 0
        for value in nums[start:]:
            total += value
            count += total == k
    return count


def test_example_1():
    """Two overlapping stretches."""
    assert count_stretches([1, 1, 1], 2) == 2


def test_example_2():
    """Zero sums, with a negative value."""
    assert count_stretches([1, -1, 0], 0) == 3


def test_empty_list():
    """An empty list has no stretches."""
    assert count_stretches([], 0) == 0


def test_no_match():
    """No stretch sums to k."""
    assert count_stretches([1, 2, 3], 7) == 0


def test_all_zeros():
    """Every one of the 10 stretches of four zeros sums to 0."""
    assert count_stretches([0, 0, 0, 0], 0) == 10


def test_small_random_lists():
    """Random short lists, compared with checking every stretch."""
    rng = random.Random(3)
    for _ in range(200):
        nums = [rng.randint(-3, 3) for _ in range(rng.randint(0, 12))]
        k = rng.randint(-4, 4)
        assert count_stretches(nums, k) == _slow(nums, k)


def test_long_list():
    """100,000 values."""
    nums = [1, -1] * 50000
    assert count_stretches(nums, 0) == 50000 * 50000

