def shortest_path(grid):
    """Return the fewest moves from the top-left to the bottom-right cell, or -1."""
    pass

problems.reference_solution:
from collections import deque


def shortest_path(grid):
    """Return the fewest moves from the top-left to the bottom-right cell, or -1."""
    rows, columns = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[-1][-1] == '#':
        return -1
    distance = {(0, 0): 0}
    queue = deque([(0, 0)])
    while queue:
        row, column = queue.popleft()
        if (row, column) == (rows - 1, columns - 1):
            return distance[row, column]
        for r, c in (row + 1, column), (row - 1, column), (row, column + 1), (row, column - 1):
            if 0 <= r < rows and 0 <= c < columns and grid[r][c] == '.' and (r, c) not in distance:
                distance[r, c] = distance[row, column] + 1
                queue.append((r, c))
    return -1

