def can_reach_end(jumps):
    """Return True when the last index of jumps can be reached from index 0."""
    pass

problems.reference_solution:
def can_reach_end(jumps):
    """Return True when the last index of jumps can be reached from index 0."""
    furthest = 0
    for i, jump in enumerate(jumps):
        if i > furthest:
            return False
        furthest = max(furthest, i + jump)
    return True
